import { tags } from "typia";

/**
 * Aggregated usage metrics for a single cancellation policy in the shoppingMall
 * platform.
 *
 * This DTO ties a specific cancellation policy (identified by code) to counts
 * of how frequently it has been applied in cancellation-related operations over
 * a particular analysis window. It is designed for use inside
 * IShoppingMallPolicyUsageStatistics and in admin-facing analytics views.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCancellationPolicyUsageStatistics = {
  /**
   * Code of the cancellation policy to which these statistics apply.
   *
   * This should match the code used in
   * IShoppingMallCancellationPolicy.ISummary and the corresponding row in
   * shopping_mall_cancellation_policies.
   */
  policyCode: string;

  /**
   * Total number of cancellation requests that were evaluated under this
   * cancellation policy in the analysis period.
   *
   * This count typically corresponds to records in
   * shopping_mall_order_cancellation_requests that reference orders governed
   * by this policy.
   */
  cancellationRequestCount: number & tags.Type<"int32">;

  /**
   * Number of orders that were successfully cancelled under this policy
   * during the analysis period.
   *
   * This is usually a subset of cancellationRequestCount, representing
   * cancellation requests that resulted in an order status change to a
   * cancelled state.
   */
  cancelledOrderCount: number & tags.Type<"int32">;
};
